__END_TEST_IDS__

for pair in "$TRAIN_IDS_SHA256 /select_train_ids.txt" "$TEST_IDS_SHA256 /select_test_ids.txt"; do
  set -- $pair
  if [ "$(sha256sum "$2" | cut -d' ' -f1)" != "$1" ]; then
    echo "id list $2 does not match the pre-registered sha256 $1" >&2
    exit "$ID_LIST_MISMATCH_EXIT"
  fi
done

case "$STAGE" in

  build)
    cd /project
    # :134-138, resolved from /wheelhouse under the reference freeze instead of the index.
    uv pip install --no-index --find-links /wheelhouse --constraints /constraints.txt \
      ".[${EXTRA_PREFIX}extra,${EXTRA_PREFIX}test,${EXTRA_PREFIX}strategies]" \
      --upgrade \
      --find-links /wheelhouse
    uv pip install --no-index --find-links /wheelhouse "setuptools<80.10.3"
    uv pip list
    # :148
    uv pip uninstall pytorch-lightning
    # :170
    rm -rf src/
    # :159-160
    python requirements/pytorch/check-avail-extras.py
    python -c "from torch import __version__ as ver; assert ver.startswith('2.6'), ver"
    ;;

  test)
    # :170; each stage starts a new container from the image, where src/ is present.
    cd /project
    rm -rf src/
    cd tests/tests_pytorch
    # :179-182
    python utilities/test_warnings.py
    # :184-191, with the pre-registered id list in place of `.`
    echo $GITHUB_RUN_ID
    mapfile -t IDS < /select_test_ids.txt
    python -m coverage run --source ${COVERAGE_SCOPE} \
      -m pytest "${IDS[@]}" -v --timeout=90 --durations=50 --random-order-seed=$GITHUB_RUN_ID \
      --junitxml=junit.xml -o junit_family=legacy
    ;;

  train)
    # :170
    cd /project
    rm -rf src/
    cd tests/tests_pytorch
    # :184-191, with the pre-registered id list in place of `.`
    echo $GITHUB_RUN_ID
    mapfile -t IDS < /select_train_ids.txt
    python -m coverage run --source ${COVERAGE_SCOPE} \
      -m pytest "${IDS[@]}" -v --timeout=90 --durations=50 --random-order-seed=$GITHUB_RUN_ID \
      --junitxml=junit.xml -o junit_family=legacy
    ;;

  *)
    echo "unknown stage: $STAGE" >&2
    exit 2
    ;;

esac
